import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.DWfJTVRq.js";const g=JSON.parse(`{"title":"Locking","description":"This page explains how several processes share one database file through the operating system's byte-range locks alone, with no shared memory and nothing for a…","frontmatter":{"title":"Locking","order":5,"prev":{"text":"Commits and recovery","link":"/engine/commits-and-recovery"},"next":{"text":"Encryption","link":"/engine/encryption"}},"headers":[{"level":2,"title":"What the locks promise","slug":"what-the-locks-promise","link":"#what-the-locks-promise","children":[]},{"level":2,"title":"Why only byte-range locks","slug":"why-only-byte-range-locks","link":"#why-only-byte-range-locks","children":[]},{"level":2,"title":"The lock bytes","slug":"the-lock-bytes","link":"#the-lock-bytes","children":[]},{"level":2,"title":"One handle per file in each process","slug":"one-handle-per-file-in-each-process","link":"#one-handle-per-file-in-each-process","children":[]},{"level":2,"title":"Opening a file","slug":"opening-a-file","link":"#opening-a-file","children":[]},{"level":2,"title":"Reading","slug":"reading","link":"#reading","children":[]},{"level":2,"title":"Writing","slug":"writing","link":"#writing","children":[{"level":3,"title":"Writers take turns","slug":"writers-take-turns","link":"#writers-take-turns","children":[]}]},{"level":2,"title":"Reclaiming pages","slug":"reclaiming-pages","link":"#reclaiming-pages","children":[]},{"level":2,"title":"When a process dies","slug":"when-a-process-dies","link":"#when-a-process-dies","children":[]},{"level":2,"title":"Platforms","slug":"platforms","link":"#platforms","children":[]}],"relativePath":"engine/locking.md","filePath":"en/engine/locking.md","lastUpdated":1791000973000}`),i={name:"engine/locking.md"};function n(r,e,l,h,c,d){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="locking" tabindex="-1">Locking <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;Locking&quot;">​</a></h1><p>This page explains how several processes share one database file through the operating system&#39;s byte-range locks alone, with no shared memory and nothing for a dead process to leave behind.</p><p>The specification is <a href="https://github.com/jooy2/darudb/blob/main/design/locking.md" target="_blank" rel="noreferrer">design/locking.md</a> in the repository. <a href="./../guide/processes">Several processes</a> shows what it means for an application.</p><h2 id="what-the-locks-promise" tabindex="-1">What the locks promise <a class="header-anchor" href="#what-the-locks-promise" aria-label="Permalink to &quot;What the locks promise&quot;">​</a></h2><ul><li>Any number of processes open the file. One of them writes at a time, and all of them can read at any time.</li><li>Readers never wait for the writer, and the writer never waits for readers.</li><li>A process that dies, at any moment and for any reason, leaves nothing that another process has to clean up or wait out.</li><li>Every platform behaves the same way, so one test suite covers all of them.</li></ul><h2 id="why-only-byte-range-locks" tabindex="-1">Why only byte-range locks <a class="header-anchor" href="#why-only-byte-range-locks" aria-label="Permalink to &quot;Why only byte-range locks&quot;">​</a></h2><p>The only state the processes share is the file&#39;s content and the operating system&#39;s byte-range locks on it: <code>fcntl</code> record locks on Unix-like systems and <code>LockFileEx</code> on Windows. The operating system releases a process&#39;s locks when the process ends, for any reason, and that is all the cleanup there is.</p><p>Coordinating through mutexes in shared memory was rejected. A process that dies holding such a mutex leaves it held, and recovering from that needs robust mutexes that not every platform has. A lock file with a memory layout in it also breaks between processes of different architectures. Designs built that way have in practice been limited to one process at a time, and making several processes on one file stable is one of the tasks DaruDB was started for.</p><h2 id="the-lock-bytes" tabindex="-1">The lock bytes <a class="header-anchor" href="#the-lock-bytes" aria-label="Permalink to &quot;The lock bytes&quot;">​</a></h2><p>Every lock is taken on a byte at 2^62 or above, far past any data:</p><table tabindex="0"><thead><tr><th>Byte</th><th>Lock</th><th>Held</th></tr></thead><tbody><tr><td>2^62</td><td>Open</td><td>Shared by every process that has the file open, and exclusively by a process recovering it</td></tr><tr><td>2^62 + 1</td><td>Writer</td><td>Exclusively, by the process whose transaction is writing</td></tr><tr><td>2^62 + 2</td><td>Recovery</td><td>Exclusively, by a process that is opening the file, until it holds the open lock</td></tr><tr><td>2^62 + 3</td><td>Turn</td><td>Exclusively, by the waiting writer whose turn is next</td></tr><tr><td>2^62 + 64 + <code>s</code></td><td>Snapshot</td><td>Shared, by every process with a read transaction on the commit whose transaction id is <code>s</code></td></tr></tbody></table><p>On Windows, byte-range locks are mandatory: bytes locked through one handle cannot be read or written through another. The file never reaches 2^62 bytes, so no read or write ever touches a lock byte. Transaction ids stay below 2^62 − 64, so that every snapshot&#39;s byte fits in a signed 64-bit offset; at a million commits a second, that lasts more than 100,000 years.</p><h2 id="one-handle-per-file-in-each-process" tabindex="-1">One handle per file in each process <a class="header-anchor" href="#one-handle-per-file-in-each-process" aria-label="Permalink to &quot;One handle per file in each process&quot;">​</a></h2><p>On Unix-like systems, a record lock belongs to the process, not to the descriptor it was taken through, and closing any descriptor of the file releases all of the process&#39;s locks on it. So each process keeps one shared instance for each database file, which holds the only operating-system handle to the file. Every database object a program opens for that file in that process uses it, and the last one to close closes the file.</p><ul><li><strong>Files are told apart by what they are</strong>, not by their path: device and inode on Unix-like systems, volume serial number and file index on Windows. Two paths to one file share one instance.</li><li><strong>Nothing else in the process may open the database file</strong>, not even to copy it. Closing that descriptor would silently drop the database&#39;s locks. A backup copies a file safely (<a href="./../guide/tools">Tools</a>).</li><li><strong>A forked child process does not inherit record locks.</strong> Every database object it inherited from its parent fails with <code>CLOSED</code>, and the child opens the file itself.</li><li><strong>The handle that opens a file first</strong> in a process decides the options every handle shares, such as the busy timeout and the size of the page cache.</li></ul><p>On Windows, a lock belongs to its handle. With one handle in each process, the behaviour is the same on every platform.</p><h2 id="opening-a-file" tabindex="-1">Opening a file <a class="header-anchor" href="#opening-a-file" aria-label="Permalink to &quot;Opening a file&quot;">​</a></h2><ol><li>Use the process&#39;s instance for the file if it has one, and stop here. Otherwise open the file.</li><li>Take the recovery lock, trying again with growing pauses; waiting past the busy timeout fails with <code>BUSY</code>.</li><li>Try to take the open lock exclusively, without waiting. Getting it means no other process has the file open: run <a href="./commits-and-recovery#recovery">recovery</a>, then turn the open lock into a shared one.</li><li>Otherwise, other processes have the file open, and the first of them recovered it. Take the open lock shared.</li><li>Release the recovery lock.</li></ol><p>A process holds the open lock only once it has recovered the file or found others holding it, never while it waits to open. If a process dies while it recovers the file after a power cut, its open lock goes with it, and the next process to take the recovery lock finds the file unopened and recovers it itself.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p>A reader takes no lock on the header. It reads, registers, and reads again:</p><ol><li>Read the first 2048 bytes of the file, and take the record in the slot the selector names. If its check fails, the writer may have been filling that slot, so read again.</li><li>Take a shared lock on the snapshot&#39;s byte, and register the snapshot in the process.</li><li>Read the selector and the published record again. If they are unchanged, the snapshot is safe to use; otherwise, unregister it and start over.</li></ol><p>A writer reuses a page only after a newer commit has stopped using it, and it looks for snapshot locks when it starts. The second read shows that the lock was in place before any such writer started, so that writer finds the lock and leaves the snapshot&#39;s pages alone.</p><p>When the last read transaction on a snapshot ends, the process keeps the snapshot&#39;s lock for 20 milliseconds, so that the next read transaction on the same commit can join it with one read of the header and no lock call: about 1 microsecond to begin instead of 2, on one Apple silicon machine. The <code>darudb-keeper</code> thread releases it after that. It goes at once when the process registers a newer snapshot, since no new read transaction can use an older one, and when the process begins a write transaction, so that it holds back none of that writer&#39;s pages.</p><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h2><ol><li>Take the process&#39;s writer gate, so that one thread at a time competes for the file.</li><li>Take the writer lock exclusively. Each attempt does not block: it is repeated with pauses of at most a millisecond until it succeeds, or until the busy timeout passes, 5 seconds by default, which fails with <code>BUSY</code>. Polling is what makes a timeout possible on every platform.</li><li>Hold both until the commit or the abort has returned.</li></ol><p>The writer writes the commit record and the selector with no further lock, since readers verify everything they read. No deadlock is possible: the writer waits for nothing while it holds the writer lock but its own barriers, and readers wait for neither lock.</p><h3 id="writers-take-turns" tabindex="-1">Writers take turns <a class="header-anchor" href="#writers-take-turns" aria-label="Permalink to &quot;Writers take turns&quot;">​</a></h3><p>Record locks do not queue waiting processes, and a writer that commits again as soon as it finishes takes the writer lock back before a pausing one wakes. So a writer that has waited 20 milliseconds claims the turn lock, and every other writer, the one that just finished included, lets it go first.</p><p>The wait trades one thing for another. A writer that commits now and then beside a busy one waits less with a shorter wait, but processes that commit in tight loops lose a little throughput on every pass of the writer lock. Measured on one Mac against a wait of 50 milliseconds, a writer committing every 10 milliseconds beside a busy one waited 22 milliseconds at the 99th percentile instead of 51, while two processes making deferred commits in tight loops made 7% fewer of them.</p><h2 id="reclaiming-pages" tabindex="-1">Reclaiming pages <a class="header-anchor" href="#reclaiming-pages" aria-label="Permalink to &quot;Reclaiming pages&quot;">​</a></h2><p>When a write transaction starts, it has to know which retained pages no snapshot can still reach, in any process. It asks one question, whether any snapshot below a given commit is registered, and bisects over the retained groups with it:</p><ul><li><strong>In this process</strong>, the registry of snapshots answers.</li><li><strong>In other processes</strong>, on Unix-like systems, <code>fcntl(F_GETLK)</code> over the range of snapshot bytes reports whether any lock lies there. It does not report the lowest one, which is why the search bisects.</li><li><strong>On Windows</strong>, which has no such query, the writer tries to take an exclusive lock over the range without waiting, and releases it at once if it is granted. A reader may wait an instant for such a probe; the writer never waits while it holds one, so the two cannot deadlock.</li></ul><h2 id="when-a-process-dies" tabindex="-1">When a process dies <a class="header-anchor" href="#when-a-process-dies" aria-label="Permalink to &quot;When a process dies&quot;">​</a></h2><p>The operating system releases its locks, and that is all the cleanup there is:</p><ul><li><strong>Its snapshots</strong> stop holding pages back, and the next writer reclaims them.</li><li><strong>The writer lock</strong> passes to the next writer, which starts from the published commit. Whatever the dead writer had written lies at free positions or in a slot that no one reads.</li><li><strong>The open lock</strong>: if it was the last process with the file open, the next one to open it runs recovery.</li><li><strong>The recovery lock</strong>, if it was opening the file: the next process waiting for it takes it, and finds the open lock free if the dead one was recovering.</li><li><strong>The turn lock</strong>: the other writers stop deferring to it.</li><li><strong>An unsynced window</strong> it left open is ended by another process that notices it, a time limit later (<a href="./commits-and-recovery#deferred-commits">Commits and recovery</a>).</li></ul><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><ul><li><strong>Linux and Android</strong>: <code>fcntl</code> record locks, through the 64-bit calls on 32-bit targets. An app&#39;s private storage supports them. Shared storage served through FUSE may not, and when the lock call reports that locks are unsupported, opening fails with <code>UNSUPPORTED_FILE_SYSTEM</code>.</li><li><strong>macOS and iOS</strong>: <code>fcntl</code> record locks, and <code>F_FULLFSYNC</code> as the barrier. On iOS, the system terminates a suspended app that holds a file lock inside an App Group container. The open lock is held for as long as the database is open, so an app whose database lives in an App Group container has to close it before the app is suspended. A database in the app&#39;s own container is not affected.</li><li><strong>Windows</strong>: <code>LockFileEx</code> and <code>UnlockFileEx</code>, with mandatory locks, which is why the lock bytes lie far from the data. There is no way to sync a directory, and none is needed on NTFS, which journals the change itself.</li><li><strong>Network file systems</strong> are refused with <code>UNSUPPORTED_FILE_SYSTEM</code>, since their locks and syncs do not keep the promises the engine relies on. Detection is a best effort: the file system&#39;s type on Linux and Android (NFS, SMB and the like), its name on macOS and iOS (<code>nfs</code>, <code>smbfs</code>, <code>afpfs</code>, <code>webdav</code>), and UNC paths and remote drives on Windows. A network file system that goes undetected is still not supported.</li><li><strong>Containers</strong> that share a local volume share the kernel, and so its locks, and work as usual. Hosts that share a volume over a network do not.</li></ul>',38)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
